#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <assert.h>
#include <string.h>

#define SKBPRIO_MAX_PRIORITY 64
#define BUG_ON(condition) do { if (condition) { printf("BUG_ON detected at line %d\n", __LINE__); exit(1); } } while(0)

typedef uint16_t u16;

struct skbprio_sched_data {
    // We simulate queues as counts for simplicity, or we can simulate precise queues.
    // Let's simulate counts.
    int queues[SKBPRIO_MAX_PRIORITY];
    u16 highest_prio;
    u16 lowest_prio;
};

struct Qdisc {
    struct skbprio_sched_data *priv;
    struct {
        int qlen;
    } q;
    int limit;
};

struct skbprio_sched_data q_data;
struct Qdisc sch;

int skb_queue_empty(int prio) {
    return q_data.queues[prio] == 0;
}

void __skb_queue_tail(int prio) {
    q_data.queues[prio]++;
}

int __skb_dequeue_tail(int prio) {
    if (q_data.queues[prio] > 0) {
        q_data.queues[prio]--;
        return 1; // Success
    }
    return 0; // Fail
}

int __skb_dequeue(int prio) {
    if (q_data.queues[prio] > 0) {
        q_data.queues[prio]--;
        return 1;
    }
    return 0;
}

static u16 calc_new_high_prio(const struct skbprio_sched_data *q)
{
    int prio;

    for (prio = q->highest_prio - 1; prio >= q->lowest_prio; prio--) {
        if (q->queues[prio] > 0)
            return prio;
    }

    return 0;
}

static u16 calc_new_low_prio(const struct skbprio_sched_data *q)
{
    int prio;

    for (prio = q->lowest_prio + 1; prio <= q->highest_prio; prio++) {
        if (q->queues[prio] > 0)
            return prio;
    }

    return SKBPRIO_MAX_PRIORITY - 1;
}

int skbprio_enqueue(int priority) {
    int max_priority = SKBPRIO_MAX_PRIORITY - 1;
    int prio = (priority < max_priority) ? priority : max_priority;
    struct skbprio_sched_data *q = sch.priv;

    if (sch.q.qlen < sch.limit) {
        __skb_queue_tail(prio);

        if (prio > q->highest_prio)
            q->highest_prio = prio;

        if (prio < q->lowest_prio) // Note: In original code logic
            q->lowest_prio = prio;

        sch.q.qlen++;
        return 0; // SUCCESS
    }

    // Limit reached
    int lp = q->lowest_prio;
    if (prio <= lp) {
        return 1; // DROP
    }

    __skb_queue_tail(prio);

    // Drop logic
    if (__skb_dequeue_tail(lp) == 0) {
        printf("BUG_ON(!to_drop)\n");
        exit(1);
    }

    if (skb_queue_empty(lp)) {
        if (q->lowest_prio == q->highest_prio) {
            BUG_ON(sch.q.qlen != 1);
            q->lowest_prio = prio;
            q->highest_prio = prio;
        } else {
            q->lowest_prio = calc_new_low_prio(q);
        }
    }

    if (prio > q->highest_prio)
        q->highest_prio = prio;

    return 2; // REPLACED
}

int skbprio_dequeue() {
    struct skbprio_sched_data *q = sch.priv;
    int hp = q->highest_prio;

    // Check if truly empty first? No, dequeue relies on highest.
    // If highest points to empty?
    if (skb_queue_empty(hp)) {
         // In original code, it dequeues then checks null.
         // But logic maintains highest non-empty.
         // If highest IS empty, we return NULL immediately?
         // No, q->qdiscs[q->highest_prio]
         // If that queue is empty, __skb_dequeue returns NULL.
    }

    if (__skb_dequeue(hp) == 0) {
        return 0; // NULL
    }

    sch.q.qlen--;

    if (skb_queue_empty(hp)) {
        if (q->lowest_prio == q->highest_prio) {
            BUG_ON(sch.q.qlen != 0);
            q->highest_prio = 0;
            q->lowest_prio = SKBPRIO_MAX_PRIORITY - 1;
        } else {
            q->highest_prio = calc_new_high_prio(q);
        }
    }
    return 1;
}

void reset() {
    memset(q_data.queues, 0, sizeof(q_data.queues));
    q_data.highest_prio = 0;
    q_data.lowest_prio = SKBPRIO_MAX_PRIORITY - 1;
    sch.q.qlen = 0;
    sch.limit = 64;
    sch.priv = &q_data;
}

int main() {
    reset();

    // Fuzzing loop or manual scenarios
    // Scenario 1: Basic replace
    sch.limit = 1;
    skbprio_enqueue(10);
    skbprio_enqueue(20); // Should replace
    assert(sch.q.qlen == 1);
    assert(q_data.queues[20] == 1);
    assert(q_data.queues[10] == 0);
    assert(q_data.highest_prio == 20);
    assert(q_data.lowest_prio == 20);

    reset();
    sch.limit = 2;
    skbprio_enqueue(10);
    skbprio_enqueue(63);
    assert(sch.q.qlen == 2);
    assert(q_data.lowest_prio == 10);
    assert(q_data.highest_prio == 63);

    // Now replace logic
    // Add 20. 20 > 10. Replace 10.
    skbprio_enqueue(20);
    // 10 becomes empty. lowest != highest (10 != 63).
    // calc_new_low_prio(q). Scans 11..63. Finds 20? No, 20 is just added.
    // Wait. 20 is added BEFORE dequeue in code:
    // __skb_queue_tail(qdisc, skb);
    // So 20 IS in queue.
    // So calc finds 20.
    assert(q_data.queues[10] == 0);
    assert(q_data.queues[20] == 1);
    assert(q_data.queues[63] == 1);
    assert(q_data.lowest_prio == 20);
    assert(q_data.highest_prio == 63);

    reset();
    // Test the "suspected" issue:
    // Packet 30.
    // Packet 40.
    sch.limit = 2;
    skbprio_enqueue(30);
    skbprio_enqueue(40);

    // Add 20. 20 < 30. Should DROP.
    skbprio_enqueue(20);
    assert(sch.q.qlen == 2);
    assert(q_data.queues[20] == 0);

    // Add 35. Replace 30.
    skbprio_enqueue(35);
    // 30 empty.
    // lowest != highest (30 != 40).
    // calc scans 31..40. Finds 35.
    assert(q_data.lowest_prio == 35);

    // Let's create the bug case.
    // lowest == highest.
    reset();
    sch.limit = 2;
    skbprio_enqueue(10);
    skbprio_enqueue(10);
    // 2 packets at 10.
    assert(sch.q.qlen == 2);
    // Add 20. Replace one 10.
    skbprio_enqueue(20);
    // 10 still has 1 packet.
    // skb_queue_empty(10) False.
    // lowest remains 10.
    // higest becomes 20.
    assert(q_data.lowest_prio == 10);
    assert(q_data.highest_prio == 20);
    assert(sch.q.qlen == 2);

    // Add 30. Replace remaining 10.
    skbprio_enqueue(30);
    // 10 becomes empty.
    // lowest(10) != highest(20).
    // calc 11..20. Finds 20.
    assert(q_data.lowest_prio == 20);
    assert(q_data.highest_prio == 30);

    // Now queues: 20 (1), 30 (1).
    // Add 40. Replace 20.
    skbprio_enqueue(40);
    // 20 becomes empty.
    // lowest(20) != highest(30).
    // calc 21..30. Finds 30.
    assert(q_data.lowest_prio == 30);

    // Now queues: 30 (1), 40 (1).
    // Add 50. Replace 30.
    skbprio_enqueue(50);
    // 30 empty.
    // lowest(30) != highest(40).
    // calc 31..40. Finds 40.
    assert(q_data.lowest_prio == 40);

    printf("All basic tests passed.\n");
    return 0;
}

